const items = $input.all();
const today = new Date().toISOString().slice(0, 10);
return items.map((item) => {
  const msg = item.json || {};
  const subject = msg.subject || '';
  const snippet = msg.snippet || '';
  const from = msg.from || '';
  const text = subject + ' ' + snippet + ' ' + from;
  const amountMatch = text.match(/\$([0-9]+\.[0-9]{2})/);
  const amount = amountMatch ? amountMatch[1] : 'unknown';
  const emailMatch = from.match(/<([^>]+)>/) || from.match(/([\w.+-]+@[\w-]+\.[\w.]+)/);
  const buyerEmail = emailMatch ? (emailMatch[1] || emailMatch[0]) : '';
  const isCashApp = /cash\.app/i.test(text) || /cash app/i.test(text);
  return {
    json: {
      'Date': today,
      'Order #': today.replace(/-/g, '') + '-' + String(msg.id || 'X').slice(-6).toUpperCase(),
      'Product': amount === '3.99' ? 'Kids book ($3.99)' : (amount === '4.99' ? 'Halloween Activity Pack ($4.99)' : 'Check payment note'),
      'Amount USD': amount,
      'Payment method': isCashApp ? 'Cash App' : 'Stripe',
      'Buyer email': buyerEmail,
      'Status': 'paid',
      'Notes': 'Logged by n8n money-check workflow'
    }
  };
});
